def frac_to_iv(s):
    """Parse an exact decimal/rational string to an exact mpmath.iv enclosure."""
    fr = Fraction(s)
    return mp.iv.mpf(fr.numerator) / mp.iv.mpf(fr.denominator)


def floor_iv_str(iv_val, digits):
    """Strict outward LOWER bound (floor) at `digits` decimal places (outward-rounded scaling)."""
    scale = 10 ** digits
    scaled_iv = iv_val * mp.iv.mpf(scale)
    lo_scaled = int(mp.floor(mp.mpf(scaled_iv.a)))
    int_part = lo_scaled // scale
    frac_part = lo_scaled % scale
    return f"{int_part}.{frac_part:0{digits}d}"


def ceil_iv_str(iv_val, digits):
    """Strict outward UPPER bound (ceil) at `digits` decimal places (outward-rounded scaling)."""
    scale = 10 ** digits
    scaled_iv = iv_val * mp.iv.mpf(scale)
    hi_scaled = int(mp.ceil(mp.mpf(scaled_iv.b)))
    int_part = hi_scaled // scale
    frac_part = hi_scaled % scale
    return f"{int_part}.{frac_part:0{digits}d}"


def ceil_sci_str(val_mp, sig=4):
    """Strict outward UPPER bound in scientific notation with `sig` significant digits (self-asserted, ZERO floats!)."""
    v = mp.mpf(val_mp)
    assert v > 0
    e = int(mp.floor(mp.log10(v)))
    while v >= mp.power(10, e + 1):
        e += 1
    while v < mp.power(10, e):
        e -= 1
    shift = sig - 1 - e
    scaled = (mp.iv.mpf(v) * mp.iv.mpf(10 ** shift)) if shift >= 0 else (mp.iv.mpf(v) / mp.iv.mpf(10 ** (-shift)))
    m_int = int(mp.ceil(mp.mpf(scaled.b)))
    if m_int >= 10 ** sig:
        m_int = 10 ** (sig - 1)
        e += 1
    s_dig = str(m_int)
    out = f"{s_dig[0]}.{s_dig[1:]}e{e:+d}" if sig > 1 else f"{s_dig}e{e:+d}"
    assert frac_to_iv(out).a >= v, f"ceil_sci_str failed outward check: {out} < {v}"
    return out


def floor_sci_str(val_mp, sig=4):
    """Strict outward LOWER bound in scientific notation with `sig` significant digits (self-asserted, ZERO floats!)."""
    v = mp.mpf(val_mp)
    assert v > 0
    e = int(mp.floor(mp.log10(v)))
    while v >= mp.power(10, e + 1):
        e += 1
    while v < mp.power(10, e):
        e -= 1
    shift = sig - 1 - e
    scaled = (mp.iv.mpf(v) * mp.iv.mpf(10 ** shift)) if shift >= 0 else (mp.iv.mpf(v) / mp.iv.mpf(10 ** (-shift)))
    m_int = int(mp.floor(mp.mpf(scaled.a)))
    if m_int < 10 ** (sig - 1):
        e -= 1
        shift = sig - 1 - e
        scaled = (mp.iv.mpf(v) * mp.iv.mpf(10 ** shift)) if shift >= 0 else (mp.iv.mpf(v) / mp.iv.mpf(10 ** (-shift)))
        m_int = int(mp.floor(mp.mpf(scaled.a)))
    s_dig = str(m_int)
    out = f"{s_dig[0]}.{s_dig[1:]}e{e:+d}" if sig > 1 else f"{s_dig}e{e:+d}"
    assert frac_to_iv(out).b <= v, f"floor_sci_str failed outward check: {out} > {v}"
    return out


