def certify_ast_zero_float():
    """Verify via Python AST that the ENTIRE script contains ZERO float literals,
       ZERO float() calls, and ZERO numpy/scipy/sympy/cvxpy imports.
    """
    src = inspect.getsource(inspect.getmodule(certify_ast_zero_float))
    tree = ast.parse(src)

    forbidden_mods = {"numpy", "scipy", "sympy", "cvxpy", "scs", "clarabel"}
    n_funcs = 0
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                assert alias.name.split(".")[0] not in forbidden_mods, f"Forbidden import: {alias.name}"
        elif isinstance(node, ast.ImportFrom) and node.module:
            assert node.module.split(".")[0] not in forbidden_mods, f"Forbidden import: {node.module}"
        elif isinstance(node, ast.FunctionDef):
            n_funcs += 1
        elif isinstance(node, ast.Constant) and isinstance(node.value, float):
            raise AssertionError(f"Float literal {node.value!r} found at line {node.lineno}")
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "float":
            raise AssertionError(f"float() call found at line {node.lineno}")
    print(f"[Module 0] AST Zero-Float Audit PASSED (ENTIRE FILE): 0 forbidden imports, 0 floats across all {n_funcs} functions & witness tables.")
    return n_funcs


