# MODULE 1: PURE EXACT INTEGER SYMBOLIC PROOF OF GLOBAL MÖBIUS MONOTONICITY
# ==============================================================================

def poly_add(A, B):
    out = dict(A)
    for k, v in B.items():
        nv = out.get(k, 0) + v
        if nv == 0:
            out.pop(k, None)
        else:
            out[k] = nv
    return out


def poly_sub(A, B):
    out = dict(A)
    for k, v in B.items():
        nv = out.get(k, 0) - v
        if nv == 0:
            out.pop(k, None)
        else:
            out[k] = nv
    return out


def poly_mul(A, B):
    out = {}
    for (e0, e1, e2), va in A.items():
        for (f0, f1, f2), vb in B.items():
            k = (e0 + f0, e1 + f1, e2 + f2)
            out[k] = out.get(k, 0) + va * vb
    return {k: v for k, v in out.items() if v != 0}


def poly_diff_d(A):
    out = {}
    for (e0, e1, e2), v in A.items():
        if e0 > 0:
            out[(e0 - 1, e1, e2)] = e0 * v
    return out


def certify_mobius_monotonicity():
    """Pure exact integer polynomial proof in Z[d, p1, p2] (d = q_+ - 1 > 0, p1, p2 >= 0) that:
         (1) For p = 3/2: L(d; p1, p2) = K_{1+d}^{(3/2)}(q(p1), x(p2)) / sig_+(1+d)
             with q = a^2 p1 / (1 + a p1), x = a^3 p2 / (1 + a p2), a = 1 + d
             satisfies -dL/dd = N / D^2 with ALL 282 monomials of N and ALL 367 of D^2 strictly >= 1!
         (2) For p = 4/3: L(d; p1, p2) = K_{1+d}^{(4/3)}(x(p1), y(p2)) / sig_+(1+d)
             with x = a^2 p1 / (1 + a p1), y = a^2 p2 / (1 + a p2), a = 1 + d
             satisfies -dL/dd = N / D^2 with ALL 223 monomials of N and ALL 271 of D^2 strictly >= 1!
    """
    ONE = {(0, 0, 0): 1}
    D_v = {(1, 0, 0): 1}
    P1 = {(0, 1, 0): 1}
    P2 = {(0, 0, 1): 1}
    a = poly_add(ONE, D_v)
    a2 = poly_mul(a, a)
    a3 = poly_mul(a2, a)

    # --- Case 1: p = 3/2 ---
    # L = 1 - q*x/sig + (1+x) / (sig*(Lam - (1+x)*q))
    # Clear common denominators using D1 = 1 + a*p1, D2 = 1 + a*p2:
    #   q = a^2 p1 / D1,  x = a^3 p2 / D2,  1 + x = (D2 + a^3 p2) / D2 =: S2 / D2
    #   Lam = (1 + a^2)^2 / a,  sig = a*(a^2 - 1) = a*d*(d+2)
    D1 = poly_add(ONE, poly_mul(a, P1))
    D2 = poly_add(ONE, poly_mul(a, P2))
    q_num = poly_mul(a2, P1)
    x_num = poly_mul(a3, P2)
    S2 = poly_add(D2, x_num)  # (1+x)*D2
    one_p_a2 = poly_add(ONE, a2)
    Lam_num = poly_mul(one_p_a2, one_p_a2)  # Lam * a
    sig = poly_mul(a, poly_sub(a2, ONE))    # a*(a^2 - 1)

    # Lam - (1+x)*q = [Lam_num * D1 * D2 - a * S2 * q_num] / (a * D1 * D2) =: M_num / (a * D1 * D2)
    M_num = poly_sub(poly_mul(Lam_num, poly_mul(D1, D2)), poly_mul(a, poly_mul(S2, q_num)))
    # Check M_num > 0 identically in Z_{>0}[d, p1, p2]!
    assert min(M_num.values()) > 0, "p=3/2 denominator M_num has non-positive monomial!"

    Den_L = poly_mul(sig, poly_mul(poly_mul(D1, D2), M_num))
    assert min(Den_L.values()) > 0, "Den_L not strictly positive!"

    # Reduced form of L - 1:
    #   -q*x/sig = -a^4 * p1 * p2 / ((a^2 - 1) * D1 * D2)
    #   +(1+x)/(sig*(Lam - (1+x)*q)) = S2 * D1 / ((a^2 - 1) * M_num)
    # Common denominator: Den_r = (a^2 - 1) * D1 * D2 * M_num
    a2m1 = poly_sub(a2, ONE)  # d*(d+2)
    a4 = poly_mul(a2, a2)
    Den_r = poly_mul(a2m1, poly_mul(poly_mul(D1, D2), M_num))
    Num_r = poly_sub(
        poly_mul(poly_mul(D1, D1), poly_mul(D2, S2)),
        poly_mul(poly_mul(a4, poly_mul(P1, P2)), M_num)
    )
    Neg_num_32 = poly_sub(poly_mul(Num_r, poly_diff_d(Den_r)), poly_mul(poly_diff_d(Num_r), Den_r))
    Den_sq_32 = poly_mul(Den_r, Den_r)
    assert min(Neg_num_32.values()) > 0, f"p=3/2 Neg_num has min coeff {min(Neg_num_32.values())}"
    assert min(Den_sq_32.values()) > 0, f"p=3/2 Den_sq has min coeff {min(Den_sq_32.values())}"
    # Also check exact boundary p1 -> inf (leading p1-degree coefficient, i.e. q = q_+):
    max_p1_n = max(k[1] for k in Neg_num_32)
    max_p1_d = max(k[1] for k in Den_sq_32)
    lead_n = {k: v for k, v in Neg_num_32.items() if k[1] == max_p1_n}
    lead_d = {k: v for k, v in Den_sq_32.items() if k[1] == max_p1_d}
    assert max_p1_n <= max_p1_d and min(lead_n.values()) > 0 and min(lead_d.values()) > 0

    # --- Case 2: p = 4/3 ---
    # L = 1 - x*y/sig43 + (1+x)(1+y)/(sig43*(Lam43 - (1+x)(1+y)))
    # x = a^2 p1 / D1, y = a^2 p2 / D2, sig43 = a*(a - 1) = a*d, Lam43 = (1+a)^3 / a
    T1 = poly_add(D1, poly_mul(a2, P1))
    T2 = poly_add(D2, poly_mul(a2, P2))
    one_p_a = poly_add(ONE, a)
    one_p_a3 = poly_mul(one_p_a, poly_mul(one_p_a, one_p_a))
    M43 = poly_sub(poly_mul(one_p_a3, poly_mul(D1, D2)), poly_mul(a, poly_mul(T1, T2)))
    assert min(M43.values()) > 0, "p=4/3 M43 not strictly positive!"
    Den43 = poly_mul(D_v, poly_mul(poly_mul(D1, D2), M43))
    Num43 = poly_sub(
        poly_mul(poly_mul(T1, T2), poly_mul(D1, D2)),
        poly_mul(poly_mul(a3, poly_mul(P1, P2)), M43)
    )
    Neg_num_43 = poly_sub(poly_mul(Num43, poly_diff_d(Den43)), poly_mul(poly_diff_d(Num43), Den43))
    Den_sq_43 = poly_mul(Den43, Den43)
    assert min(Neg_num_43.values()) > 0, f"p=4/3 Neg_num has min coeff {min(Neg_num_43.values())}"
    assert min(Den_sq_43.values()) > 0
    # Also check exact boundary p1 -> inf (leading p1-degree coefficient, i.e. x = a) for p = 4/3:
    max_p1_n43 = max(k[1] for k in Neg_num_43)
    max_p1_d43 = max(k[1] for k in Den_sq_43)
    lead_n43 = {k: v for k, v in Neg_num_43.items() if k[1] == max_p1_n43}
    lead_d43 = {k: v for k, v in Den_sq_43.items() if k[1] == max_p1_d43}
    assert max_p1_n43 <= max_p1_d43 and min(lead_n43.values()) > 0 and min(lead_d43.values()) > 0

    print(f"[Module 1] Pure Exact Integer Symbolic Möbius Monotonicity PROVED:")
    print(f"    p=3/2: -d(K/sig)/d(q_+) = N / D^2 with {len(Neg_num_32)} N-monomials (min={min(Neg_num_32.values())}, max={max(Neg_num_32.values())}), {len(Den_sq_32)} D^2-monomials (min={min(Den_sq_32.values())}); M_num has {len(M_num)} pos monomials.")
    print(f"    p=4/3: -d(K/sig)/d(a)   = N / D^2 with {len(Neg_num_43)} N-monomials (min={min(Neg_num_43.values())}, max={max(Neg_num_43.values())}), {len(Den_sq_43)} D^2-monomials (min={min(Den_sq_43.values())}); M43   has {len(M43)} pos monomials.")
    return len(Neg_num_32), len(Neg_num_43)


