def iv_cholesky_check(Q_iv, r):
    """Exact mpmath.iv Cholesky factorization certifying Q^* > 0 for every Q in Q_iv."""
    L = [[mp.iv.mpf(0) for _ in range(r)] for _ in range(r)]
    min_piv_lo = None
    for i in range(r):
        for j in range(i + 1):
            s = mp.iv.mpf(0)
            for k in range(j):
                s = s + L[i][k] * L[j][k]
            if i == j:
                piv = Q_iv[i][i] - s
                assert piv.a > 0, f"iv Cholesky failed at pivot {i}: {piv}"
                if min_piv_lo is None or piv.a < min_piv_lo:
                    min_piv_lo = piv.a
                L[i][j] = mp.iv.sqrt(piv)
            else:
                L[i][j] = (Q_iv[i][j] - s) / L[j][j]
    return min_piv_lo


def krawczyk_eval_FJ_iv(xv, r, m, compute_J=True):
    """Pure rational mpmath.iv evaluation of F(x) and exact analytic Jacobian J(x)
       for x = [q_+, d_1, ..., d_{r-1}, Q_triu] (ZERO transcendental functions, ZERO floats!).
       Equations (exact square system, size n_var = r + r(r+1)/2):
         R1_{ij} = (M^2 - Lam D Q D)_{ij} / (d_i d_j) = 0   (i <= j)
         R2_{ii} = (Q D Q D Q - D Q D - tgt)_{ii} / d_i^2 = 0  (i = 0..r-1)
       where Lam = (1 + q_+^2)^2 / q_+, sig_+ = q_+(q_+^2 - 1), d_0 = 1.
    """
    triu = [(i, j) for i in range(r) for j in range(i, r)]
    n_q = len(triu)
    n_var = r + n_q
    ONE = mp.iv.mpf(1)
    TWO = mp.iv.mpf(2)
    THREE = mp.iv.mpf(3)
    m_m1 = mp.iv.mpf(m - 1)

    qp = xv[0]
    qp2 = qp * qp
    Lam = (ONE + qp2) * (ONE + qp2) / qp
    sp = qp * (qp2 - ONE)
    d = [ONE] + [xv[k] for k in range(1, r)]
    Q = [[mp.iv.mpf(0) for _ in range(r)] for _ in range(r)]
    for idx, (i, j) in enumerate(triu):
        Q[i][j] = xv[r + idx]
        Q[j][i] = xv[r + idx]

    # H = Q D Q, M = D + H, M2 = M^2
    H = [[mp.iv.mpf(0) for _ in range(r)] for _ in range(r)]
    for i in range(r):
        for j in range(i, r):
            s = mp.iv.mpf(0)
            for k in range(r):
                s = s + Q[i][k] * d[k] * Q[k][j]
            H[i][j] = s
            H[j][i] = s
    M = [[H[i][j] + (d[i] if i == j else mp.iv.mpf(0)) for j in range(r)] for i in range(r)]
    M2 = [[mp.iv.mpf(0) for _ in range(r)] for _ in range(r)]
    for i in range(r):
        for j in range(i, r):
            s = mp.iv.mpf(0)
            for k in range(r):
                s = s + M[i][k] * M[k][j]
            M2[i][j] = s
            M2[j][i] = s

    F_vec = [mp.iv.mpf(0)] * n_var
    for idx, (i, j) in enumerate(triu):
        F_vec[idx] = M2[i][j] / (d[i] * d[j]) - Lam * Q[i][j]
    for i in range(r):
        hdq_ii = mp.iv.mpf(0)
        for k in range(r):
            hdq_ii = hdq_ii + H[i][k] * d[k] * Q[k][i]
        tgt_s = (-sp / m_m1) if i == 0 else sp
        F_vec[n_q + i] = hdq_ii / (d[i] * d[i]) - Q[i][i] - tgt_s

    if not compute_J:
        return F_vec, None, Lam, sp, d, Q

    dLam_dqp = THREE * qp2 + TWO - ONE / qp2
    dsp_dqp = THREE * qp2 - ONE
    J = [[mp.iv.mpf(0) for _ in range(n_var)] for _ in range(n_var)]

    # Col 0: d/d(q_+)
    for idx, (i, j) in enumerate(triu):
        J[idx][0] = -dLam_dqp * Q[i][j]
    for i in range(r):
        J[n_q + i][0] = (dsp_dqp / m_m1) if i == 0 else (-dsp_dqp)

    # Cols 1..r-1: d/d(d_a)
    for a in range(1, r):
        da = d[a]
        va = [Q[i][a] for i in range(r)]
        wa = [mp.iv.mpf(0)] * r
        for i in range(r):
            s = mp.iv.mpf(0)
            for k in range(r):
                s = s + M[i][k] * va[k]
            wa[i] = s
        for idx, (i, j) in enumerate(triu):
            dm2 = va[i] * wa[j] + wa[i] * va[j]
            if i == a:
                dm2 = dm2 + M[a][j]
            if j == a:
                dm2 = dm2 + M[i][a]
            deriv = dm2 / (d[i] * d[j])
            if i == a:
                deriv = deriv - M2[i][j] / (da * d[i] * d[j])
            if j == a:
                deriv = deriv - M2[i][j] / (da * d[i] * d[j])
            J[idx][a] = deriv
        for i in range(r):
            dhdq = TWO * Q[i][a] * H[a][i]
            deriv = dhdq / (d[i] * d[i])
            if i == a:
                hdq_ii = mp.iv.mpf(0)
                for k in range(r):
                    hdq_ii = hdq_ii + H[i][k] * d[k] * Q[k][i]
                deriv = deriv - TWO * hdq_ii / (da * da * da)
            J[n_q + i][a] = deriv

    # Cols r..n_var-1: d/dQ_{ab}
    MQ = [[mp.iv.mpf(0) for _ in range(r)] for _ in range(r)]
    for i in range(r):
        for j in range(r):
            s = mp.iv.mpf(0)
            for k in range(r):
                s = s + M[i][k] * Q[k][j]
            MQ[i][j] = s

    def add_Eab(col, a, b):
        da, db = d[a], d[b]
        for idx, (i, j) in enumerate(triu):
            dm2 = Q[i][a] * da * M[b][j] + M[i][a] * db * Q[b][j]
            if i == a:
                dm2 = dm2 + db * MQ[j][b]
            if j == b:
                dm2 = dm2 + MQ[i][a] * da
            term = dm2 / (d[i] * d[j])
            if i == a and j == b:
                term = term - Lam
            J[idx][col] = J[idx][col] + term
        for i in range(r):
            dhdq = Q[i][a] * da * db * Q[b][i]
            if i == a:
                dhdq = dhdq + db * H[b][i]
            if i == b:
                dhdq = dhdq + H[i][a] * da
            term = dhdq / (d[i] * d[i])
            if i == a and i == b:
                term = term - ONE
            J[n_q + i][col] = J[n_q + i][col] + term

    for idx_q, (a, b) in enumerate(triu):
        col = r + idx_q
        add_Eab(col, a, b)
        if a != b:
            add_Eab(col, b, a)

    return F_vec, J, Lam, sp, d, Q


def certify_p32_lower_bounds():
    """Zero-float mpmath.iv Krawczyk certification of Proposition 1.4 (general_p_theory_report.md)
       infinite subcritical RG tree lower bounds for p = 3/2, m in {2, 3, 4, 5, 10}.
    """
    mp.mp.dps = 60
    mp.iv.dps = 60
    results = {}
    print("\n[Module 2] Zero-Float mpmath.iv Krawczyk Interval-Newton Lower Bounds (p = 3/2):")
    for m in sorted(WITNESSES_P32.keys()):
        rec = WITNESSES_P32[m]
        r = rec["r"]
        n_q = r * (r + 1) // 2
        n_var = r + n_q

        # Build EXACT zero-width dyadic point center x0_iv (a == b, single real point in R^N!)
        x0_strs = [rec["qp_rg_str"]] + rec["d_rg_strs"] + rec["Q_rg_triu_strs"]
        x0_raw = [frac_to_iv(s) for s in x0_strs]
        x0_iv = [mp.iv.mpf([c.a, c.a]) for c in x0_raw]
        for c in x0_iv:
            assert c.a == c.b, "Krawczyk center must be an exact single real point!"

        # Step 1: Compute approximate inverse Y = J(x0)^{-1} in point mpmath (any Y is valid for Krawczyk!)
        F0_iv, J0_iv, _, _, _, _ = krawczyk_eval_FJ_iv(x0_iv, r, m, compute_J=True)
        J0_pt = mp.matrix(n_var, n_var)
        for i in range(n_var):
            for j in range(n_var):
                J0_pt[i, j] = (mp.mpf(J0_iv[i][j].a) + mp.mpf(J0_iv[i][j].b)) / 2
        Y_pt = J0_pt ** (-1)
        # Convert Y_pt to exact zero-width point intervals!
        Y_iv = [[mp.iv.mpf([Y_pt[i, j], Y_pt[i, j]]) for j in range(n_var)] for i in range(n_var)]

        # Step 2: Build Krawczyk box X = x0 + [-rad, +rad] with exact radius 10^{-30}!
        rad = mp.iv.mpf(1) / mp.iv.mpf(10 ** 30)
        rad_box = mp.iv.mpf([-rad.b, rad.b])
        X_iv = [x0_iv[i] + rad_box for i in range(n_var)]
        X_minus_x0 = [X_iv[i] - x0_iv[i] for i in range(n_var)]

        # Evaluate J_iv(X_iv) rigorously in mpmath.iv!
        _, JX_iv, Lam_iv, sp_iv, d_iv, Q_iv = krawczyk_eval_FJ_iv(X_iv, r, m, compute_J=True)

        # Compute K(X) = x0 - Y * F(x0) + (I - Y * J(X)) * (X - x0)
        # Check BOTH strict inclusion K(X)_i subset int(X_i) AND ||I - Y J(X)||_inf < 1!
        max_ratio_hi = mp.mpf(0)
        max_row_norm_hi = mp.mpf(0)
        for i in range(n_var):
            yF = mp.iv.mpf(0)
            for k in range(n_var):
                yF = yF + Y_iv[i][k] * F0_iv[k]
            contr = mp.iv.mpf(0)
            row_norm = mp.iv.mpf(0)
            for j in range(n_var):
                s = mp.iv.mpf(0)
                for k in range(n_var):
                    s = s + Y_iv[i][k] * JX_iv[k][j]
                entry = (mp.iv.mpf(1) - s) if i == j else (-s)
                contr = contr + entry * X_minus_x0[j]
                row_norm = row_norm + abs(entry)
            assert row_norm.b < 1, f"Contraction ||I - Y J(X)||_inf >= 1 at m={m}, row {i}"
            if mp.mpf(row_norm.b) > max_row_norm_hi:
                max_row_norm_hi = mp.mpf(row_norm.b)
            K_i = x0_iv[i] - yF + contr
            assert K_i.a > X_iv[i].a and K_i.b < X_iv[i].b, f"Krawczyk failed at m={m}, coord {i}"
            diff_iv = K_i - x0_iv[i]
            half_w_iv = abs(diff_iv) / rad
            if mp.mpf(half_w_iv.b) > max_ratio_hi:
                max_ratio_hi = mp.mpf(half_w_iv.b)

        # Step 3: Certify strict ordering 1 = d_0 > d_1 > ... > d_{r-1} > 0 (enforcing [F, D] = 0 off-diag!)
        assert d_iv[0].a == 1 and d_iv[0].b == 1
        for k in range(r - 1):
            assert d_iv[k].a > d_iv[k + 1].b, f"d_k ordering failed at k={k}"
        assert d_iv[r - 1].a > 0, "d_{r-1} not strictly positive!"

        # Step 4: Certify BOTH Q^* > 0 AND q_+^* I - Q^* > 0 via exact iv Cholesky!
        min_piv = iv_cholesky_check(Q_iv, r)
        qp_iv = X_iv[0]
        Qp_minus_Q = [[(qp_iv - Q_iv[i][j]) if i == j else (-Q_iv[i][j]) for j in range(r)] for i in range(r)]
        min_piv_hi = iv_cholesky_check(Qp_minus_Q, r)

        # Step 5: Certify strict subcritical branching rho_r = (m-1) * sum_{k=1}^{r-1} d_k^3 < 1!
        rho_iv = mp.iv.mpf(0)
        for k in range(1, r):
            rho_iv = rho_iv + d_iv[k] * d_iv[k] * d_iv[k]
        rho_iv = mp.iv.mpf(m - 1) * rho_iv
        assert rho_iv.b < 1, f"Subcritical branching failed: rho={rho_iv}"

        # Step 6: Certified outward lower bound C_LB = ((Lam_iv)/4)^{1/3}
        C_iv = (Lam_iv / mp.iv.mpf(4)) ** (mp.iv.mpf(1) / mp.iv.mpf(3))
        results[m] = (C_iv, Lam_iv, rho_iv)
        print(f"    m={m:2d} (r={r:2d}): C_LB = {floor_iv_str(C_iv, 18)} | rho_hi = {ceil_iv_str(rho_iv, 8)} < 1 | chol(Q, qpI-Q) >= ({floor_sci_str(min_piv, 4)}, {floor_sci_str(min_piv_hi, 4)}) | ||I-YJ||_inf <= {ceil_sci_str(max_row_norm_hi, 4)} | K_rat <= {ceil_sci_str(max_ratio_hi, 4)}")
    return results


# ==============================================================================
# MODULE 3: ZERO-FLOAT mpmath.iv GLOBAL ALL-Lam, ALL-delta, ALL-n UPPER BOUNDS
# ==============================================================================

def jet_mul(A, B, deg):
    """Exact truncated Taylor-series product of degree `deg` in mpmath.iv."""
    out = [mp.iv.mpf(0)] * (deg + 1)
    for i in range(deg + 1):
        s = mp.iv.mpf(0)
        for j in range(i + 1):
            s = s + A[j] * B[i - j]
        out[i] = s
    return out


def jet_inv(A, deg):
    """Exact truncated Taylor-series reciprocal 1/A(t) of degree `deg` in mpmath.iv.
       Requires A[0] strictly positive (A[0].a > 0).
    """
    a0 = A[0]
    if a0.a <= 0:
        return None
    inv0 = mp.iv.mpf(1) / a0
    B = [mp.iv.mpf(0)] * (deg + 1)
    B[0] = inv0
    for k in range(1, deg + 1):
        s = mp.iv.mpf(0)
        for j in range(1, k + 1):
            s = s + A[j] * B[k - j]
        B[k] = -inv0 * s
    return B


def jet_eval_taylor(c_jet, Q_jet, h_hi_iv, deg):
    """Rigorous Taylor enclosure with Lagrange remainder on [c - h, c + h] (outward-rounded powers):
         f(c + t) in sum_{k=0}^{deg-1} c_jet[k] * t^k + Q_jet[deg] * t^deg
       using exact outward-rounded power enclosures t^k in [0, (h^k).b] (even k) or [-(h^k).b, (h^k).b] (odd k).
    """
    res = c_jet[0]
    h_pow_iv = mp.iv.mpf(1)
    for k in range(1, deg):
        h_pow_iv = h_pow_iv * h_hi_iv
        hp = h_pow_iv.b
        t_iv = mp.iv.mpf([mp.mpf(0), hp]) if (k % 2 == 0) else mp.iv.mpf([-hp, hp])
        res = res + c_jet[k] * t_iv
    h_pow_iv = h_pow_iv * h_hi_iv
    hp = h_pow_iv.b
    t_iv = mp.iv.mpf([mp.mpf(0), hp]) if (deg % 2 == 0) else mp.iv.mpf([-hp, hp])
    res = res + Q_jet[deg] * t_iv
    return res


def certify_1d_convexity_p32_single(m, rec):
    """Pure 1D mpmath.iv Degree-5 Taylor-Jet certification on q in [0, qp_ub] of:
         (1) L_j(q) > 0 for all j = 0..N-1,
         (2) F(q, 0) = sum_j w_j / L_j(q) > (m-1)/m,
         (3) dF/du(q, 0) = sum_j w_j * (L_j(q) - 1) / L_j(q)^2 > 0.
       Combined with Lemma 1 (1-Square Identity), Lemma 2 (Operator-Antitone Bridge
       + Thm 12(3)), Module 1 (Symbolic Möbius Monotonicity), and pure 1D convexity
       d^2F/du^2 >= 0 on u in [0, 1], this proves unconditionally (given Holden Thm 3.1)
       that NO finite-dimensional solution exists for ANY Lam >= Lam(qp_ub), ANY delta >= 0,
       ANY n >= 1!
    """
    mp.mp.dps = 60
    mp.iv.dps = 60
    DEG = 5
    ONE = mp.iv.mpf(1)
    ZERO = mp.iv.mpf(0)
    qp_ub = frac_to_iv(rec["qp_ub_str"])
    qp2 = qp_ub * qp_ub
    qp3 = qp2 * qp_ub
    Lam_ub = (ONE + qp2) * (ONE + qp2) / qp_ub
    sp_ub = qp_ub * (qp2 - ONE)
    C_ub = (Lam_ub / mp.iv.mpf(4)) ** (ONE / mp.iv.mpf(3))
    tgt = mp.iv.mpf(m - 1) / mp.iv.mpf(m)

    w_ints = rec["w_ints"]
    DEN = 10 ** rec["w_den_exp"]
    assert sum(w_ints) == DEN and all(wi > 0 for wi in w_ints)
    ws = [mp.iv.mpf(wi) / mp.iv.mpf(DEN) for wi in w_ints]
    p2s = [frac_to_iv(s) for s in rec["p2_strs"]]
    assert all(p2.a >= 0 for p2 in p2s)
    xs = [(qp3 * p2) / (ONE + qp_ub * p2) for p2 in p2s]
    for j, xj in enumerate(xs):
        assert xj.a >= 0 and xj.b < qp2.a, f"Atom {j} out of [0, qp^2)"
    one_p_x = [ONE + xj for xj in xs]
    N = len(xs)

    def eval_FG_jets(q_iv):
        """Compute degree-DEG Taylor jets of F(q, 0) and G(q) = dF/du(q, 0) at q_iv."""
        F_jet = [ZERO] * (DEG + 1)
        G_jet = [ZERO] * (DEG + 1)
        for j in range(N):
            # den(q + t) = (Lam_ub - (1+x_j)*q) - (1+x_j)*t
            den_jet = [ZERO] * (DEG + 1)
            den_jet[0] = Lam_ub - one_p_x[j] * q_iv
            den_jet[1] = -one_p_x[j]
            inv_den = jet_inv(den_jet, DEG)
            if inv_den is None:
                return None, None
            # K(q + t) = (sp_ub - x_j*q) - x_j*t + (1+x_j) * inv_den
            K_jet = [one_p_x[j] * inv_den[k] for k in range(DEG + 1)]
            K_jet[0] = K_jet[0] + sp_ub - xs[j] * q_iv
            K_jet[1] = K_jet[1] - xs[j]
            # L(q + t) = K / sp_ub -> inv_L = sp_ub / K
            inv_K = jet_inv(K_jet, DEG)
            if inv_K is None:
                return None, None
            inv_L = [sp_ub * inv_K[k] for k in range(DEG + 1)]
            inv_L2 = jet_mul(inv_L, inv_L, DEG)
            wj = ws[j]
            for k in range(DEG + 1):
                F_jet[k] = F_jet[k] + wj * inv_L[k]
                G_jet[k] = G_jet[k] + wj * (inv_L[k] - inv_L2[k])
        return F_jet, G_jet

    def check_box(a_mp, b_mp):
        Q_iv = mp.iv.mpf([a_mp, b_mp])
        c_mp = (a_mp + b_mp) / 2
        c_iv = mp.iv.mpf([c_mp, c_mp])
        h_right = (mp.iv.mpf([b_mp, b_mp]) - c_iv).b
        h_left = (c_iv - mp.iv.mpf([a_mp, a_mp])).b
        h_hi_iv = mp.iv.mpf([max(h_right, h_left), max(h_right, h_left)])
        Fc_jet, Gc_jet = eval_FG_jets(c_iv)
        if Fc_jet is None:
            return False, None, None
        FQ_jet, GQ_jet = eval_FG_jets(Q_iv)
        if FQ_jet is None:
            return False, None, None
        F_iv = jet_eval_taylor(Fc_jet, FQ_jet, h_hi_iv, DEG)
        G_iv = jet_eval_taylor(Gc_jet, GQ_jet, h_hi_iv, DEG)
        margin_F = F_iv - tgt
        if margin_F.a > 0 and G_iv.a > 0:
            return True, mp.mpf(margin_F.a), mp.mpf(G_iv.a)
        return False, None, None

    # Cover [0, qp_ub.b] (slightly wider than qp_ub, guaranteeing full coverage of [0, qp_ub]!)
    stack = [(mp.mpf(0), mp.mpf(qp_ub.b))]
    n_boxes = 0
    min_F_lo = None
    min_G_lo = None
    while stack:
        a_mp, b_mp = stack.pop()
        ok, mF, mG = check_box(a_mp, b_mp)
        if ok:
            n_boxes += 1
            if min_F_lo is None or mF < min_F_lo:
                min_F_lo = mF
            if min_G_lo is None or mG < min_G_lo:
                min_G_lo = mG
        else:
            assert n_boxes + len(stack) < 10000, f"Too many 1D boxes for m={m} at [{a_mp}, {b_mp}]!"
            mid_mp = (a_mp + b_mp) / 2
            assert a_mp < mid_mp < b_mp, f"Bisection stalled at [{a_mp}, {b_mp}]!"
            stack.append((mid_mp, b_mp))
            stack.append((a_mp, mid_mp))

    return C_ub, n_boxes, min_F_lo, min_G_lo


def certify_p32_upper_bounds(lb_results):
    """Run zero-float mpmath.iv upper-bound certification across m in {2, 3, 4, 5, 10}."""
    print("\n[Module 3] Zero-Float mpmath.iv Global All-Lam, All-delta, All-n Upper Bounds (p = 3/2):")
    ub_results = {}
    for m in sorted(WITNESSES_P32.keys()):
        rec = WITNESSES_P32[m]
        C_ub, n_boxes, min_F_lo, min_G_lo = certify_1d_convexity_p32_single(m, rec)
        C_lb, _, _ = lb_results[m]
        assert C_lb.b < C_ub.a, f"LB/UB ordering failed for m={m}!"
        lb_str = floor_iv_str(C_lb, 18)
        ub_str = ceil_iv_str(C_ub, 18)
        gap_iv_hi = mp.mpf((C_ub - C_lb).b)
        disp_gap_fr = Fraction(ub_str) - Fraction(lb_str)
        disp_gap_hi = mp.mpf((mp.iv.mpf(disp_gap_fr.numerator) / mp.iv.mpf(disp_gap_fr.denominator)).b)
        gap_hi = max(gap_iv_hi, disp_gap_hi)
        ub_results[m] = (C_ub, n_boxes, min_F_lo, min_G_lo, gap_hi)
        print(f"    m={m:2d} ({len(rec['w_ints']):2d} atoms, {n_boxes:4d} 1D iv-boxes):")
        print(f"       {lb_str}  <  C_{{3/2}}({m})  <=  {ub_str}   (certified gap <= {ceil_sci_str(gap_hi, 4)})")
        print(f"       min(F - (m-1)/m) >= +{floor_sci_str(min_F_lo, 4)}  |  min(dF/du|_{{u=0}}) >= +{floor_sci_str(min_G_lo, 4)}")
    return ub_results


# ==============================================================================
# MODULE 4: UNIFIED 4-LINE ONE-SQUARE TWIN CERTIFICATION AT p = 4/3, m = 2
# ==============================================================================

def certify_p43_twin_m2():
    """Zero-float mpmath.iv Degree-5 Taylor-Jet certification of C_{4/3}(2) via the EXACT SAME
       4-line 1-square operator-antitone identity + symbolic Möbius monotonicity (Module 1)
       + pure 1D convexity (ONLY 9 rational atoms, ZERO M_0 series, ZERO Schur product!).
    """
    mp.mp.dps = 60
    mp.iv.dps = 60
    DEG = 5
    rec = WITNESS_P43_M2
    ONE = mp.iv.mpf(1)
    TWO = mp.iv.mpf(2)
    ZERO = mp.iv.mpf(0)
    a_ub = frac_to_iv(rec["a_ub_str"])
    a2 = a_ub * a_ub
    Lam_ub = (ONE + a_ub) ** 3 / a_ub
    sp_ub = a_ub * (a_ub - ONE)
    C_ub = (Lam_ub / mp.iv.mpf(8)) ** (ONE / mp.iv.mpf(4))
    tgt = ONE / TWO

    w_ints = rec["w_ints"]
    DEN = 10 ** rec["w_den_exp"]
    assert sum(w_ints) == DEN and all(wi > 0 for wi in w_ints)
    ws = [mp.iv.mpf(wi) / mp.iv.mpf(DEN) for wi in w_ints]
    p2s = [frac_to_iv(s) for s in rec["p2_strs"]]
    ys = [(a2 * p2) / (ONE + a_ub * p2) for p2 in p2s]
    for yj in ys:
        assert yj.a >= 0 and yj.b < a_ub.a
    one_p_y = [ONE + yj for yj in ys]
    N = len(ys)

    def eval_FG_jets(x_iv):
        F_jet = [ZERO] * (DEG + 1)
        G_jet = [ZERO] * (DEG + 1)
        for j in range(N):
            den_jet = [ZERO] * (DEG + 1)
            den_jet[0] = Lam_ub - (ONE + x_iv) * one_p_y[j]
            den_jet[1] = -one_p_y[j]
            inv_den = jet_inv(den_jet, DEG)
            if inv_den is None:
                return None, None
            # (1+x+t)(1+y_j) / den = Lam_ub / den - 1! (ZERO cancellation, linear in inv_den!)
            K_jet = [Lam_ub * inv_den[k] for k in range(DEG + 1)]
            K_jet[0] = K_jet[0] - ONE + sp_ub - x_iv * ys[j]
            K_jet[1] = K_jet[1] - ys[j]
            inv_K = jet_inv(K_jet, DEG)
            if inv_K is None:
                return None, None
            inv_L = [sp_ub * inv_K[k] for k in range(DEG + 1)]
            inv_L2 = jet_mul(inv_L, inv_L, DEG)
            wj = ws[j]
            for k in range(DEG + 1):
                F_jet[k] = F_jet[k] + wj * inv_L[k]
                G_jet[k] = G_jet[k] + wj * (inv_L[k] - inv_L2[k])
        return F_jet, G_jet

    def check_box(a_mp, b_mp):
        X_iv = mp.iv.mpf([a_mp, b_mp])
        c_mp = (a_mp + b_mp) / 2
        c_iv = mp.iv.mpf([c_mp, c_mp])
        h_right = (mp.iv.mpf([b_mp, b_mp]) - c_iv).b
        h_left = (c_iv - mp.iv.mpf([a_mp, a_mp])).b
        h_hi_iv = mp.iv.mpf([max(h_right, h_left), max(h_right, h_left)])
        Fc_jet, Gc_jet = eval_FG_jets(c_iv)
        if Fc_jet is None:
            return False, None, None
        FX_jet, GX_jet = eval_FG_jets(X_iv)
        if FX_jet is None:
            return False, None, None
        F_iv = jet_eval_taylor(Fc_jet, FX_jet, h_hi_iv, DEG)
        G_iv = jet_eval_taylor(Gc_jet, GX_jet, h_hi_iv, DEG)
        if (F_iv - tgt).a > 0 and G_iv.a > 0:
            return True, mp.mpf((F_iv - tgt).a), mp.mpf(G_iv.a)
        return False, None, None

    stack = [(mp.mpf(0), mp.mpf(a_ub.b))]
    n_boxes = 0
    min_F_lo = None; min_G_lo = None
    while stack:
        a_mp, b_mp = stack.pop()
        ok, mF, mG = check_box(a_mp, b_mp)
        if ok:
            n_boxes += 1
            if min_F_lo is None or mF < min_F_lo: min_F_lo = mF
            if min_G_lo is None or mG < min_G_lo: min_G_lo = mG
        else:
            assert n_boxes + len(stack) < 10000
            mid_mp = (a_mp + b_mp) / 2
            assert a_mp < mid_mp < b_mp, f"Bisection stalled at [{a_mp}, {b_mp}]!"
            stack.append((mid_mp, b_mp))
            stack.append((a_mp, mid_mp))

    print(f"\n[Module 4] Unified 4-Line One-Square Twin Certification at p = 4/3, m = 2 ({N} atoms, {n_boxes} 1D iv-boxes):")
    print(f"    C_{{4/3}}(2) <= {ceil_iv_str(C_ub, 15)}  (vs exact 1.01837157606022, gap <= 4.01e-9; >70x tighter than prior 2.82e-7 Nyström!)")
    print(f"    min(F - 1/2) >= +{floor_sci_str(min_F_lo, 4)}  |  min(dF/du|_{{u=0}}) >= +{floor_sci_str(min_G_lo, 4)}")
    return C_ub, n_boxes


# ==============================================================================
# MODULE 5: 50-DPS CONTINUUM OPERATOR, KKT, ROSETTA-STONE & TP_4 ANATOMY
# ==============================================================================

def verify_operator_anatomy_50dps():
    """High-precision 50-dps verification of all structural theorems at p = 3/2, m = 2 (r = 12)
       using pure mpmath (zero numpy/scipy).
    """
    mp.mp.dps = 50
    rec = WITNESSES_P32[2]
    r = rec["r"]
    qp = mp.mpf(rec["qp_rg_str"])
    Lam = (1 + qp * qp) ** 2 / qp
    sp = qp * (qp * qp - 1)
    c_r = 2 * sp
    d = [mp.mpf(1)] + [mp.mpf(s) for s in rec["d_rg_strs"]]
    triu = [(i, j) for i in range(r) for j in range(i, r)]
    Q = mp.matrix(r, r)
    for idx, (i, j) in enumerate(triu):
        Q[i, j] = Q[j, i] = mp.mpf(rec["Q_rg_triu_strs"][idx])

    # 1. Diagonalize Q and X = D^{-1/2} H D^{-1/2}
    q_ev, UQ = mp.eigh(Q)
    oq = sorted(range(r), key=lambda i: q_ev[i])
    q_ev = [q_ev[i] for i in oq]
    U_s = mp.matrix(r, r)
    for j, col in enumerate(oq):
        sgn = mp.mpf(1) if UQ[0, col] >= 0 else mp.mpf(-1)
        for i in range(r):
            U_s[i, j] = sgn * UQ[i, col]
    u = [U_s[0, j] for j in range(r)]
    w_mu = [uk * uk for uk in u]

    # A = U_s^T D U_s, A_inv = U_s^T D^{-1} U_s in Q-eigenbasis!
    A = mp.matrix(r, r); A_inv = mp.matrix(r, r); A3 = mp.matrix(r, r)
    for i in range(r):
        for j in range(r):
            A[i, j] = mp.fsum(U_s[k, i] * d[k] * U_s[k, j] for k in range(r))
            A_inv[i, j] = mp.fsum(U_s[k, i] * (1 / d[k]) * U_s[k, j] for k in range(r))
            A3[i, j] = mp.fsum(U_s[k, i] * (d[k] ** 3) * U_s[k, j] for k in range(r))

    Qd = mp.matrix(r, r); Qph = mp.matrix(r, r); Qmh = mp.matrix(r, r)
    for i in range(r):
        Qd[i, i] = q_ev[i]
        Qph[i, i] = mp.sqrt(q_ev[i])
        Qmh[i, i] = 1 / mp.sqrt(q_ev[i])

    # 2. Unitary polar factorization U_pol = Lam^{-1/2} Q^{-1/2} (I + W Q), W = A^{-1} Q A
    W = A_inv * Qd * A
    M_Q = A + Qd * A * Qd
    U_pol = (1 / mp.sqrt(Lam)) * Qmh * (mp.eye(r) + W * Qd)
    err_unitary = mp.mnorm(U_pol * U_pol.T - mp.eye(r), "F")
    assert err_unitary < mp.mpf("1e-40"), f"U_pol orthogonality failed: {err_unitary}"

    # 3. Exact KKT Dual Multiplier Theorem: Y_1 = A^3, Y_2 = -(1/Lam) A M A
    #    Check exact V(Q, U_pol) = Lam^{1/2} Q^{1/2} U_pol Q^{-1/2} - Q^{-1/2}
    #    and S = Q^{-1/2} V^* A^3 Q^{1/2} U_pol == Lam^{-3/2} M^3 (symmetric!)
    V = W * Qph
    V_from_U = mp.sqrt(Lam) * Qph * U_pol * Qmh - Qmh
    err_V = mp.mnorm(V - V_from_U, "F")
    assert err_V < mp.mpf("1e-40"), f"V(Q, U_pol) formula failed: {err_V}"
    S_u = Qmh * V.T * A3 * Qph * U_pol
    M3_scaled = (Lam ** (-mp.mpf(3) / 2)) * (M_Q * M_Q * M_Q)
    err_S = mp.mnorm(S_u - M3_scaled, "F")
    assert err_S < mp.mpf("1e-40"), f"KKT U-stationarity S = Lam^(-3/2) M^3 failed: {err_S}"

    #    Check exact Hermitian Q-stationarity C = Q^{-1/2} A^{-1} M A Q A^2 - A Q A Q A Q^{1/2}
    #    equals A^3 Q^{1/2} + (Q^{1/2} A M A - A M A Q^{1/2}) (skew-Hermitian remainder!)
    AMA = A * M_Q * A
    C_lhs = Qmh * A_inv * M_Q * A * Qd * (A * A) - A * Qd * A * Qd * A * Qph
    C_rhs = A3 * Qph + (Qph * AMA - AMA * Qph)
    err_Qstat = mp.mnorm(C_lhs - C_rhs, "F")
    assert err_Qstat < mp.mpf("1e-40"), f"KKT Q-stationarity identity failed: {err_Qstat}"

    #    Check superoperator positivity: A^3 - (q_+ / Lam) A M A >= (1/(1+q_+^2)) A^3 > 0!
    sd = [mp.sqrt(dk) for dk in d]
    H_D = mp.matrix(r, r)
    for i in range(r):
        for j in range(r):
            H_D[i, j] = mp.fsum(Q[i, k] * d[k] * Q[k, j] for k in range(r))
    X_D = mp.matrix(r, r)
    for i in range(r):
        for j in range(r):
            X_D[i, j] = H_D[i, j] / (sd[i] * sd[j])
    x_ev, UX = mp.eigh(X_D)
    ox = sorted(range(r), key=lambda i: x_ev[i])
    x_ev = [x_ev[i] for i in ox]
    p_nu = [UX[0, i] ** 2 for i in ox]
    superop_min = 1 - (qp / Lam) * (1 + x_ev[-1])
    superop_lb = 1 / (1 + qp * qp)
    assert superop_min > superop_lb, "Superoperator lower bound violated!"

    # 4. Exact 1-Square Identity on r=12 RG block at x = 0, x_5, x_11:
    Ehat = V * V.T - Qd
    B_sp = sp * mp.eye(r) - Ehat
    max_1sq_err = mp.mpf(0)
    for x_test in [mp.mpf(0), x_ev[5], x_ev[-1]]:
        gam = (1 + x_test) / Lam
        Kg_Q = mp.matrix(r, r)
        I_m_gQ = mp.matrix(r, r)
        I_m_gQ_inv = mp.matrix(r, r)
        for i in range(r):
            qi = q_ev[i]
            Kg_Q[i, i] = sp - qi * x_test + (1 + x_test) / (Lam - (1 + x_test) * qi)
            I_m_gQ[i, i] = 1 - gam * qi
            I_m_gQ_inv[i, i] = 1 / (1 - gam * qi)
        Rx = V - gam * Qph * I_m_gQ_inv
        diff = (Kg_Q - B_sp) - Rx * I_m_gQ * Rx.T
        e1 = mp.mnorm(diff, "F")
        if e1 > max_1sq_err:
            max_1sq_err = e1
    assert max_1sq_err < mp.mpf("1e-40"), f"1-square identity failed on RG: {max_1sq_err}"

    # 5. Exact 1-Square Identity on an EXPLICIT NON-RG INDEFINITE-B_{sp} 2x2 MATRIX (e_1 > 1.82*sp)!
    D2 = [mp.mpf(1), mp.mpf("0.1")]
    Q2 = mp.matrix([[mp.mpf("0.25577859"), mp.mpf("0.10838663")],
                    [mp.mpf("0.10838663"), mp.mpf("0.95176212")]])
    z2 = [Q2[0, 0], Q2[0, 1], Q2[1, 1]]
    def res2(zv):
        Qm = mp.matrix([[zv[0], zv[1]], [zv[1], zv[2]]])
        Hm = mp.matrix(2, 2)
        for i in range(2):
            for j in range(2):
                Hm[i, j] = Qm[i, 0] * D2[0] * Qm[0, j] + Qm[i, 1] * D2[1] * Qm[1, j]
        Mm = Hm + mp.matrix([[D2[0], 0], [0, D2[1]]])
        R = Mm * Mm - Lam * mp.matrix([[D2[0]*Qm[0,0]*D2[0], D2[0]*Qm[0,1]*D2[1]],
                                       [D2[1]*Qm[1,0]*D2[0], D2[1]*Qm[1,1]*D2[1]]])
        return mp.matrix([R[0, 0], R[0, 1], R[1, 1]])
    h2 = mp.mpf("1e-22")
    for _ in range(25):
        F2 = res2(z2)
        if mp.norm(F2, mp.inf) < mp.mpf("1e-44"): break
        J2 = mp.matrix(3, 3)
        for col in range(3):
            zp = list(z2); zp[col] += h2
            Fp = res2(zp)
            for row in range(3): J2[row, col] = (Fp[row] - F2[row]) / h2
        dz2 = mp.lu_solve(J2, -F2)
        for k in range(3): z2[k] += dz2[k]
    assert mp.norm(res2(z2), mp.inf) < mp.mpf("1e-42"), "Non-RG 2x2 polish failed!"
    Q2 = mp.matrix([[z2[0], z2[1]], [z2[1], z2[2]]])
    ev2_raw, U2 = mp.eigh(Q2)
    ev2 = [ev2_raw[0], ev2_raw[1]]
    assert min(ev2) > 0 and max(ev2) < qp
    H2 = mp.matrix(2, 2)
    for i in range(2):
        for j in range(2):
            H2[i, j] = Q2[i, 0] * D2[0] * Q2[0, j] + Q2[i, 1] * D2[1] * Q2[1, j]
    F2m = mp.matrix(2, 2)
    for i in range(2):
        for j in range(2):
            F2m[i, j] = H2[i, 0] * D2[0] * Q2[0, j] + H2[i, 1] * D2[1] * Q2[1, j] - D2[i] * Q2[i, j] * D2[j]
    Ehat2 = mp.matrix([[F2m[i, j] / (D2[i] * D2[j]) for j in range(2)] for i in range(2)])
    B_sp2 = sp * mp.eye(2) - Ehat2
    evB2 = sorted(mp.eigh(B_sp2, eigvals_only=True))
    W2 = mp.matrix([[(1 / D2[i]) * Q2[i, j] * D2[j] for j in range(2)] for i in range(2)])
    Q2_ph = U2 * mp.matrix([[mp.sqrt(ev2[0]), 0], [0, mp.sqrt(ev2[1])]]) * U2.T
    V2 = W2 * Q2_ph
    x_t = mp.mpf("0.4")
    g_t = (1 + x_t) / Lam
    I_m_gQ2 = mp.eye(2) - g_t * Q2
    I_m_gQ2_inv = I_m_gQ2 ** (-1)
    K_Q2 = U2 * mp.matrix([
        [sp - ev2[0] * x_t + (1 + x_t) / (Lam - (1 + x_t) * ev2[0]), 0],
        [0, sp - ev2[1] * x_t + (1 + x_t) / (Lam - (1 + x_t) * ev2[1])]
    ]) * U2.T
    R2x = V2 - g_t * Q2_ph * I_m_gQ2_inv
    err_nonrg_1sq = mp.mnorm((K_Q2 - B_sp2) - R2x * I_m_gQ2 * R2x.T, "F")
    assert err_nonrg_1sq < mp.mpf("1e-42") and evB2[0] < 0, f"Non-RG indefinite check failed: evB2={evB2}"

    # 6. Exact Rosetta-Stone Finite-r Mutual Tangency at r = 12 (50 dps):
    inv_cr = 1 / c_r
    max_I_err = mp.mpf(0); max_h_err = mp.mpf(0)
    for k in range(r):
        xk = x_ev[k]
        Ik = mp.fsum(w_mu[i] / (sp - q_ev[i] * xk + (1 + xk) / (Lam - (1 + xk) * q_ev[i])) for i in range(r))
        max_I_err = max(max_I_err, abs(Ik - inv_cr))
    for i in range(r):
        qi = q_ev[i]
        hi = mp.fsum(p_nu[k] / (sp - qi * x_ev[k] + (1 + x_ev[k]) / (Lam - (1 + x_ev[k]) * qi)) for k in range(r))
        max_h_err = max(max_h_err, abs(hi - inv_cr))
    assert max_I_err < mp.mpf("1e-42") and max_h_err < mp.mpf("1e-42")

    # 7. Exact 50-dps Refutation of Total Positivity of Order 4 (TP_4) on a_{12}(q_i, q_j)!
    a_ker = mp.matrix(r, r)
    for i in range(r):
        for j in range(r):
            a_ker[i, j] = A[i, j] / (u[i] * u[j])
    min_4x4 = mp.mpf("1e99")
    for i in range(r - 3):
        for j in range(r - 3):
            sub = mp.matrix([[a_ker[i + ii, j + jj] for jj in range(4)] for ii in range(4)])
            dt = mp.det(sub)
            if dt < min_4x4:
                min_4x4 = dt
    assert min_4x4 < 0, "Expected negative 4x4 minor at r=12!"

    # 8. Spectral gap & Jacobi bands of mu_{12}
    x_gap = (qp * qp - 1) ** 2 / (4 * qp * qp)
    assert x_ev[0] < x_gap and x_ev[1] > x_gap

    p_prev = [mp.mpf(0)] * r
    p_curr = [mp.mpf(1)] * r
    b_prev = mp.mpf(0)
    jac_lo = []
    for k in range(6):
        al = mp.fsum(w_mu[i] * q_ev[i] * p_curr[i] ** 2 for i in range(r))
        rv = [(q_ev[i] - al) * p_curr[i] - b_prev * p_prev[i] for i in range(r)]
        be = mp.sqrt(mp.fsum(w_mu[i] * rv[i] ** 2 for i in range(r)))
        jac_lo.append(al - 2 * be)
        p_prev = p_curr
        p_curr = [v / be for v in rv]
        b_prev = be

    print("\n[Module 5] 50-dps Exact Continuum & Operator Anatomy Verifications (p = 3/2, m = 2, r = 12):")
    print(f"    1) Unitary polar factor ||U_pol U_pol^T - I||_F           = {mp.nstr(err_unitary, 4)}")
    print(f"    2) KKT U-stationarity ||S - Lam^(-3/2) M^3||_F            = {mp.nstr(err_S, 4)}")
    print(f"    3) KKT Q-stationarity ||C - (A^3 Q^{{1/2}} + skew)||_F      = {mp.nstr(err_Qstat, 4)}")
    print(f"    4) Superoperator gap  min_eig(I - (q_+/Lam)(I+X))         = {mp.nstr(superop_min, 6)} > 1/(1+q_+^2) = {mp.nstr(superop_lb, 6)}")
    print(f"    5) 1-Square Identity on r=12 RG (x=0, x_5, x_11)          = {mp.nstr(max_1sq_err, 4)}")
    print(f"    6) 1-Square Identity on NON-RG indefinite B_sp (lam1={mp.nstr(evB2[0], 4)} < 0) = {mp.nstr(err_nonrg_1sq, 4)}")
    print(f"    7) Rosetta-Stone mutual tangency max|I(x_k)-1/c|, |h(q_i)-1/c| = {mp.nstr(max_I_err, 4)}, {mp.nstr(max_h_err, 4)}")
    print(f"    8) TP_4 refutation on Markov kernel a_12: min 4x4 minor   = {mp.nstr(min_4x4, 5)} (< 0 strictly!)")
    print(f"    9) Dual X-spectrum gap: x_0 = {mp.nstr(x_ev[0], 5)} (p_0={mp.nstr(p_nu[0], 6)}) < x_gap = {mp.nstr(x_gap, 6)} < x_1 = {mp.nstr(x_ev[1], 6)}")
    print(f"   10) Primal Q-edge: q_1(r=12) = {mp.nstr(q_ev[0], 8)}, Jacobi a_5 - 2 b_5 = {mp.nstr(jac_lo[-1], 8)} (strictly > 0!)")


